(function () {
/**
 * 拼多多 · 「指定类目 × 整数 VID 全区间」强制假一赔十完整扫描器
 * ==================================================================
 * 为什么用整数扫描而不是品牌库扫描：
 *   规则接口 POST /glide/v2/mms/query/rules/limit/new 接受**任意 vid**，
 *   不要求该 vid 是"已注册品牌"。因此逐整数扫描区间 [from, to] 后，
 *   该区间内的结果**可证明完整** —— 不依赖品牌库枚举的覆盖度。
 *
 * 完整性口径：
 *   ✅ 已扫过的整数区间内：100% 完整（除重试中断，脚本会记录）
 *   ❌ 未扫的区间：不保证（vid 空间上限约 595 万）
 *
 * 可靠性设计：
 *   - 双限流码 55555 / 40002 指数退避重试
 *   - 失败 vid 进 failed 队列，主流程后多轮补扫
 *   - 每 1000 次进度写 localStorage 检查点 → 页面刷新后可续跑
 *   - 内置自检：扫完后核对已知强制 vid 是否全部命中
 *
 * 用法（在已登录发布页控制台）：
 *   await runIntegerSweep(5908, { from: 1, to: 1000000, conc: 6 })
 *   arkSweepStatus()          // 进度 / ETA
 *   arkSweepExport(5908)      // 导出已扫出的强制品牌 CSV
 *   arkSweepCheckpoint(5908)  // 手动存检查点
 */

const ARK_REF = 310;
const ARK_SWEEP_KEY = c => 'ark_isweep_' + c;

function arkS(ms) { return new Promise(r => setTimeout(r, ms)); }

async function arkRuleOne(catId, vid, S) {
  for (let a = 0; a < 8; a++) {
    try {
      const r = await fetch('/glide/v2/mms/query/rules/limit/new', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ cat_id: catId, goods_type: 1, goods_properties: [{ ref_pid: ARK_REF, vid: vid }] })
      });
      const j = await r.json();
      if (j && j.success) {
        return { must: j.result.is_must_fake_one_lose_ten === true, notShow: j.result.is_not_show_fake_one_lose_ten === true };
      }
      const code = String(j && (j.error_code || j.errorCode));
      if (code === '55555' || code === '40002') { S.throttled++; await arkS(Math.min(1500 * (a + 1), 12000)); continue; }
      return { other: code };
    } catch (e) { await arkS(600 * (a + 1)); }
  }
  return null;
}

function arkSweepCheckpoint(catId) {
  const S = window.__arkSweep;
  if (!S) return null;
  try {
    localStorage.setItem(ARK_SWEEP_KEY(catId), JSON.stringify({ next: S.next, to: S.to, tested: S.tested, ok: S.ok, must: S.must, notShow: S.notShow, failed: S.failed, throttled: S.throttled, ts: Date.now() }));
    return 'saved';
  } catch (e) { return 'save-failed: ' + e.message; }
}

async function runIntegerSweep(catId, opts) {
  opts = opts || {};
  const from = opts.from || 1;
  const to = opts.to || 1000000;
  const conc = opts.conc || 6;
  const resume = opts.resume !== false;

  let saved = null;
  if (resume) { try { saved = JSON.parse(localStorage.getItem(ARK_SWEEP_KEY(catId)) || 'null'); } catch (e) { saved = null; } }

  const S = window.__arkSweep = (saved && saved.to === to && saved.next > from && saved.next <= to)
    ? { catId: catId, from: from, to: to, next: saved.next, tested: saved.tested, ok: saved.ok, must: saved.must, notShow: saved.notShow, failed: saved.failed || [], throttled: saved.throttled || 0, conc: conc, done: false, resumed: true, started: Date.now(), rounds: 0 }
    : { catId: catId, from: from, to: to, next: from, tested: 0, ok: 0, must: [], notShow: [], failed: [], throttled: 0, conc: conc, done: false, resumed: false, started: Date.now(), rounds: 0 };

  let sinceCkpt = 0;
  const run = async (isRetry) => {
    const worker = async () => {
      while (true) {
        let v;
        if (isRetry) { if (!S.failed.length) return; v = S.failed.pop(); }
        else { if (S.next > S.to) return; v = S.next++; }
        const r = await arkRuleOne(catId, v, S);
        S.tested++;
        if (r === null) { if (!isRetry) S.failed.push(v); }
        else {
          S.ok++;
          if (r.must) S.must.push(v);
          if (r.notShow) S.notShow.push(v);
        }
        if (!isRetry && ++sinceCkpt >= 1000) { sinceCkpt = 0; arkSweepCheckpoint(catId); }
      }
    };
    await Promise.all(Array.from({ length: S.conc }, worker));
  };

  await run(false);
  while (S.failed.length && S.rounds < 6) {
    S.rounds++;
    await arkS(3000);
    await run(true);
  }
  S.done = true; S.finishedAt = Date.now();
  arkSweepCheckpoint(catId);

  // 自检：已知强制 vid 必须全部命中
  const known = [11646, 132, 17779, 17780, 17781, 17782, 17787, 17789, 17795, 31130, 2687, 33847, 450, 101, 8906, 17784, 22254, 71272, 17790];
  S.selfCheck = { known: known.length, missing: known.filter(v => v >= from && v <= to && S.must.indexOf(v) < 0) };

  if (opts.download) arkSweepExport(catId);
  return S;
}

function arkSweepStatus() {
  const S = window.__arkSweep;
  if (!S) return 'no sweep';
  const span = S.to - S.from + 1;
  const done = S.next - S.from;
  const mins = (Date.now() - S.started) / 60000;
  const rate = S.tested / Math.max(mins, 1);
  return {
    catId: S.catId, range: S.from + '-' + S.to, resumed: S.resumed,
    done: done, span: span, pct: Math.round(done / span * 1000) / 10 + '%',
    tested: S.tested, ok: S.ok, must: S.must.length, pendingFailed: S.failed.length,
    throttled: S.throttled, rounds: S.rounds, perMin: Math.round(rate),
    etaMin: rate > 0 ? Math.round((span - done) / rate) : null, finished: S.done, selfCheck: S.selfCheck || null
  };
}

function arkSweepExport(catId, filename) {
  const S = window.__arkSweep;
  if (!S) return null;
  const map = window.__brandMap2 || (window.__big && window.__big.map) || {};
  const rows = S.must.slice().sort((a, b) => a - b).map(v => [catId, v, map[v] === undefined ? '' : map[v]]);
  arkSweepCsv(filename || ('强制假一赔十_整数全扫_' + catId + '.csv'), rows);
  return { catId: catId, forced: rows.length, rangeScanned: S.from + '-' + (S.next - 1), tested: S.tested };
}

function arkSweepCsv(filename, rows, header) {
  header = header || ['cat_id', 'brand_vid', 'brand_name'];
  const q = s => '"' + String(s === undefined || s === null ? '' : s).replace(/"/g, '""') + '"';
  const csv = '\uFEFF' + [header.map(q).join(',')].concat(rows.map(r => r.map(q).join(','))).join('\r\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 3000);
}

console.log('%c[ark] 整数区间扫描器就绪：await runIntegerSweep(类目ID,{from:1,to:1000000}) · arkSweepStatus() · arkSweepExport(类目ID)', 'color:#ff7300');

  window.__ark = { runIntegerSweep: runIntegerSweep, arkSweepStatus: arkSweepStatus, arkSweepExport: arkSweepExport, arkSweepCheckpoint: arkSweepCheckpoint, arkRuleOne: arkRuleOne, arkSweepCsv: arkSweepCsv };
  return JSON.stringify({
    exposed: Object.keys(window.__ark),
    launcher: window.__isweepLauncher ? window.__isweepLauncher.state : null,
    sweep: window.__arkSweep ? { next: window.__arkSweep.next, to: window.__arkSweep.to, tested: window.__arkSweep.tested } : null,
    brandMap2: window.__brandMap2 ? Object.keys(window.__brandMap2).length : null,
    bconv: window.__bconv ? { charsDone: window.__bconv.charsDone, charsKnown: window.__bconv.charsKnown, round: window.__bconv.round, done: window.__bconv.done } : null
  });
})()
